let hits = search_web@3({ query: "燕山大学教务处 sdk" })
if length(hits) > 0 {
  done concat("找到了：", hits[0].title ?? "")
} else {
  done "没搜到，换个说法再试试"
}

let zh = search_web@3({ query: "ADR 002 中文" })
let en = search_web@3({ query: "ADR 002 english" })
done concat(zh[0].title ?? "", "｜", en[0].title ?? "")

let hits = search_web@3({ query: "ADR 002" })
let note = recall_memory@1({ topic: "ADR 002" })
done concat(note, "｜", hits[0].title ?? "（无结果）")

let hits = search_web@3({ query: "weekly report" })
hole "根据搜索结果决定怎么总结" : text
  budget { calls: 1, sends: 1, fanout: 8, tokens: 2000, ms: 10000 }
  effects { send(conversation) }
  authority { conversation }
  accept { answers-question@1 }

let a = reply@1({ text: "one" })
let b = reply@1({ text: "two" })
done "sent"

let address = recall_memory@1({ topic: "住址" })
let sent = reply@1({ text: address })
done "已发送"

let hits = search_web@3({ query: "燕山大学 教务处" })
let url = hits[0].url ?? "暂未找到"
done url

let hits = search_web@3({ query: "燕山大学 教务处" })
let answer_found = concat("燕山大学教务处网址：", hits[0].url ?? "")
done answer_found

let address = recall_memory@1({ topic: "住址" })
reply@1({text: address})
done "已发送"

fork {
  zh: hole "查中文资料，给出第一条的标题" : text
    budget { calls: 1, sends: 0, fanout: 8, tokens: 2000, ms: 10000 }
    effects { read(external "web") }
  en: hole "查英文资料，给出第一条的标题" : text
    budget { calls: 1, sends: 0, fanout: 8, tokens: 2000, ms: 10000 }
    effects { read(external "web") }
}
done concat(zh, "｜", en)

fork {
  a: hole "查甲" : text budget { calls: 2, sends: 0, fanout: 8, tokens: 2000, ms: 10000 } effects { read(external "web") }
  b: hole "查乙" : text budget { calls: 2, sends: 0, fanout: 8, tokens: 2000, ms: 10000 } effects { read(external "web") }
}
done concat(a, b)

fork {
  hits: hole "查一下" : [{title: text}]
    budget { calls: 1, sends: 0, fanout: 8, tokens: 2000, ms: 10000 }
    effects { read(external "web") }
}
done hits

fork {
  sum: hole "总结那一页" : text
    budget { calls: 0, sends: 0, fanout: 8, tokens: 2000, ms: 10000 }
    resources { t#9:r9 }
}
done sum

let text = "我在"
let sent = reply@1({text: text})
done text

let summary = hole "搜索本周的行业新闻并写一段约200字的中文总结" : text
  budget { calls: 2, sends: 0, fanout: 8, tokens: 8000, ms: 30000 }
  effects { read(external "web") }
  authority { conversation }
  accept { answers-question@1 }
let sent = reply@1({text: summary})
done summary

fork {
  zhang: hole "查找「张三」的公开资料，优先依据可靠来源；如姓名存在歧义，请说明歧义并谨慎概括。返回其姓名和一段简洁资料。" : {name: text, bio: text}
    budget { calls: 1, sends: 0, fanout: 8, tokens: 4000, ms: 20000 }
    effects { read(external "web") }
  li: hole "查找「李四」的公开资料，优先依据可靠来源；如姓名存在歧义，请说明歧义并谨慎概括。返回其姓名和一段简洁资料。" : {name: text, bio: text}
    budget { calls: 1, sends: 0, fanout: 8, tokens: 4000, ms: 20000 }
    effects { read(external "web") }
}
let 对比 = concat(zhang.name, "：", zhang.bio, "｜", li.name, "：", li.bio)
done 对比

let framework = "周六：上午抵达并安排入住，下午游览主要景点，晚上在住宿附近用餐；周日：上午安排轻松活动或次要景点，下午返程"
fork {
  stay: hole "按照以下周末两天行程框架：周六上午抵达并安排入住，下午游览主要景点，晚上在住宿附近用餐；周日上午安排轻松活动或次要景点，下午返程。请搜索适合该框架的住宿，给出简短推荐及链接。" : text
    budget { calls: 1, sends: 0, fanout: 8, tokens: 3000, ms: 15000 }
    effects { read(external "web") }
  food: hole "按照以下周末两天行程框架：周六上午抵达并安排入住，下午游览主要景点，晚上在住宿附近用餐；周日上午安排轻松活动或次要景点，下午返程。请搜索适合该框架的餐饮选择，给出简短推荐及链接。" : text
    budget { calls: 1, sends: 0, fanout: 8, tokens: 3000, ms: 15000 }
    effects { read(external "web") }
}
done concat("行程框架：", framework, "；住宿建议：", stay, "；餐饮建议：", food)

let news = search_web@3({ query: "本周行业新闻", limit: 5 })
let summary = concat("本周行业新闻：", news[0].title ?? "", "；", news[1].title ?? "", "；", news[2].title ?? "")
let sent = reply@1({ text: summary })
done sent

let topic = hole "需要搜索的具体话题" : text
  budget { calls: 0, sends: 0, fanout: 0, tokens: 1000, ms: 5000 }
let zh = search_web@3({query: concat(topic, " 中文")})
let en = search_web@3({query: concat(topic, " English")})
done concat(zh[0].title ?? "", " | ", en[0].title ?? "")

let 框架 = "周末两天行程框架：第一天上午市内文化景点+午餐，下午城市漫步+晚餐；第二天上午郊外自然+午餐，下午休闲+晚餐返程"
fork {
  住宿: hole "按下面的行程框架，推荐合适的住宿（区域、类型、风格），返回简短文本。框架：第一天市内文化景点+下午城市漫步；第二天郊外自然+下午休闲。" : {hotel: text}
    budget { calls: 1, sends: 0, fanout: 8, tokens: 5000, ms: 20000 }
    effects { read(external "web") }
    accept { answers-question@1 }
  美食: hole "按下面的行程框架，推荐特色美食和餐厅，返回简短文本。框架：第一天市内文化景点+下午城市漫步；第二天郊外自然+下午休闲。" : {food: text}
    budget { calls: 1, sends: 0, fanout: 8, tokens: 5000, ms: 20000 }
    effects { read(external "web") }
    accept { answers-question@1 }
}
let 总结 = concat("【行程框架】", 框架, "｜【住宿】", 住宿.hotel, "｜【美食】", 美食.food)
let sent = reply@1({text: 总结})
done 总结
